function arrayBufferToBase64(buffer2) {
  const bytes = new Uint8Array(buffer2);
  let binary = "";
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}
