function buildResumeText2(profile3, workExperiences, education, skills) {
  const sections = [];
  sections.push("=== PROFILE ===");
  sections.push(`Name: ${profile3.firstName || ""} ${profile3.lastName || ""}`);
  sections.push(`Email: ${profile3.email}`);
  sections.push(`Phone: ${profile3.phone || "Not provided"}`);
  sections.push(`Location: ${profile3.location || "Not provided"}`);
  sections.push(`LinkedIn: ${profile3.linkedInUrl || "Not provided"}`);
  sections.push(`Professional Summary: ${profile3.summary || "Not provided"}`);
  sections.push("");
  sections.push("=== WORK EXPERIENCE ===");
  if (workExperiences.length === 0) {
    sections.push("No work experience listed");
  } else {
    workExperiences.sort((a, b) => {
      const aDate = a.startDate ? new Date(a.startDate).getTime() : 0;
      const bDate = b.startDate ? new Date(b.startDate).getTime() : 0;
      return bDate - aDate;
    }).forEach((exp) => {
      sections.push(`
${exp.title} at ${exp.company}`);
      sections.push(`${formatDate(exp.startDate)} - ${exp.current ? "Present" : formatDate(exp.endDate || null)}`);
      sections.push(`Location: ${exp.location || "Not specified"}`);
      if (exp.description) {
        sections.push(`Description: ${exp.description}`);
      }
    });
  }
  sections.push("");
  sections.push("=== EDUCATION ===");
  if (education.length === 0) {
    sections.push("No education listed");
  } else {
    education.forEach((edu) => {
      sections.push(`
${edu.degree || "Degree not specified"} in ${edu.field || "Field not specified"}`);
      sections.push(`${edu.school}`);
      sections.push(`${formatDate(edu.startDate || null)} - ${formatDate(edu.endDate || null)}`);
      if (edu.gpa) {
        sections.push(`GPA: ${edu.gpa}`);
      }
    });
  }
  sections.push("");
  sections.push("=== SKILLS ===");
  if (skills.length === 0) {
    sections.push("No skills listed");
  } else {
    sections.push(skills.map((s) => s.name).join(", "));
  }
  sections.push("");
  return sections.join("\n");
}
